macro_rules! deps {
    () => {
        MetaItemInner!();
        AttrStyle!();
        CommentKind!();
    };
}

macro_rules! AttributeExt {
    () => {
        deps!();
        pub trait AttributeExt : Debug { fn id (& self) -> AttrId ; # [doc = " For a single-segment attribute (i.e., `#[attr]` and not `#[path::atrr]`),"] # [doc = " return the name of the attribute; otherwise, returns `None`."] fn name (& self) -> Option < Symbol > { self . ident () . map (| ident | ident . name) } # [doc = " Get the meta item list, `#[attr(meta item list)]`"] fn meta_item_list (& self) -> Option < ThinVec < MetaItemInner > > ; # [doc = " Gets the value literal, as string, when using `#[attr = value]`"] fn value_str (& self) -> Option < Symbol > ; # [doc = " Gets the span of the value literal, as string, when using `#[attr = value]`"] fn value_span (& self) -> Option < Span > ; # [doc = " For a single-segment attribute, returns its ident; otherwise, returns `None`."] fn ident (& self) -> Option < Ident > ; # [doc = " Checks whether the path of this attribute matches the name."] # [doc = ""] # [doc = " Matches one segment of the path to each element in `name`"] fn path_matches (& self , name : & [Symbol]) -> bool ; # [doc = " Returns `true` if it is a sugared doc comment (`///` or `//!` for example)."] # [doc = " So `#[doc = \"doc\"]` (which is a doc comment) and `#[doc(...)]` (which is not"] # [doc = " a doc comment) will return `false`."] fn is_doc_comment (& self) -> bool ; # [inline] fn has_name (& self , name : Symbol) -> bool { self . ident () . map (| x | x . name == name) . unwrap_or (false) } # [inline] fn has_any_name (& self , names : & [Symbol]) -> bool { names . iter () . any (| & name | self . has_name (name)) } # [doc = " get the span of the entire attribute"] fn span (& self) -> Span ; fn is_word (& self) -> bool ; fn path (& self) -> SmallVec < [Symbol ; 1] > { self . ident_path () . map (| i | i . into_iter () . map (| i | i . name) . collect ()) . unwrap_or (smallvec ! [sym :: doc]) } # [doc = " Returns None for doc comments"] fn ident_path (& self) -> Option < SmallVec < [Ident ; 1] > > ; # [doc = " Returns the documentation if this is a doc comment or a sugared doc comment."] # [doc = " * `///doc` returns `Some(\"doc\")`."] # [doc = " * `#[doc = \"doc\"]` returns `Some(\"doc\")`."] # [doc = " * `#[doc(...)]` returns `None`."] fn doc_str (& self) -> Option < Symbol > ; fn is_proc_macro_attr (& self) -> bool { [sym :: proc_macro , sym :: proc_macro_attribute , sym :: proc_macro_derive] . iter () . any (| kind | self . has_name (* kind)) } fn is_automatically_derived_attr (& self) -> bool ; # [doc = " Returns the documentation and its kind if this is a doc comment or a sugared doc comment."] # [doc = " * `///doc` returns `Some((\"doc\", CommentKind::Line))`."] # [doc = " * `/** doc */` returns `Some((\"doc\", CommentKind::Block))`."] # [doc = " * `#[doc = \"doc\"]` returns `Some((\"doc\", CommentKind::Line))`."] # [doc = " * `#[doc(...)]` returns `None`."] fn doc_str_and_comment_kind (& self) -> Option < (Symbol , CommentKind) > ; # [doc = " Returns outer or inner if this is a doc attribute or a sugared doc"] # [doc = " comment, otherwise None."] # [doc = ""] # [doc = " This is used in the case of doc comments on modules, to decide whether"] # [doc = " to resolve intra-doc links against the symbols in scope within the"] # [doc = " commented module (for inner doc) vs within its parent module (for outer"] # [doc = " doc)."] fn doc_resolution_scope (& self) -> Option < AttrStyle > ; }
    };
}

AttributeExt!();